type Mode int

const (
	ModeFields Mode = iota
	ModeBytes
	ModeCharacters
	ModeLines
)

type SingleBound struct {
	Idx      int
	Raw      string
	Fallback *string
}

type RangeBound struct {
	Start    *int
	StartRaw string
	End      *int
	EndRaw   string
	Fallback *string
}

type BoundItem struct {
	IsRange bool
	Single  SingleBound
	Range   RangeBound
}

type BoundPlaceholder struct {
	Items []BoundItem
}

type FormatPart struct {
	IsPlaceholder bool
	Literal       string
	Placeholder   BoundPlaceholder
}

type FormatString struct {
	IsFormat bool
	Parts    []FormatPart
	Plain    []BoundItem
}

type Config struct {
	Mode            Mode
	Bounds          FormatString
	BoundsRaw       string
	Delimiter       string
	DelimiterSet    bool
