	Join            bool
	JoinSet         bool
	NoJoin          bool
	NoJoinSet       bool
	JSON            bool
	NoMmap          bool
	RegexStr        string
	Regex           *regexp.Regexp
	Replace         *string
	Trim            string
	FallbackOOB     *string
	FixedMemory     int
	FilePath        string
}

func parseUserBoundsList(raw string) ([]BoundItem, error) {
	if raw == "" {
		return nil, fmt.Errorf("UserBoundsList must contain at least one UserBounds")
	}
	parts := strings.Split(raw, ",")
	var items []BoundItem
	for _, part := range parts {
		if part == "" {
			return nil, fmt.Errorf("Field format error: empty field")
		}
		if strings.Contains(part, ":") {
			// Range bound
			var rangeSpec string
			var fallbackVal *string
			if strings.Contains(part, "=") {
				eqIdx := strings.Index(part, "=")
				rangeSpec = part[:eqIdx]
				fb := part[eqIdx+1:]
				fallbackVal = &fb
			} else {
				rangeSpec = part
			}

			if rangeSpec == ":" {
				return nil, fmt.Errorf("Field format error, no numbers next to `:`")
			}

			colonIdx := strings.Index(rangeSpec, ":")
			leftStr := rangeSpec[:colonIdx]
			rightStr := rangeSpec[colonIdx+1:]

			var left *int
			var leftVal int
			if leftStr != "" {
				if leftStr == "0" || leftStr == "-0" {
					return nil, fmt.Errorf("Zero is not a valid field")
				}
				v, err := strconv.Atoi(leftStr)
				if err != nil {
					return nil, fmt.Errorf("Not a number `%s`", leftStr)
				}
				leftVal = v
				left = &leftVal
			}

			var right *int
			var rightVal int
			if rightStr != "" {
				if rightStr == "0" || rightStr == "-0" {
					return nil, fmt.Errorf("Zero is not a valid field")
				}
				v, err := strconv.Atoi(rightStr)
				if err != nil {
					return nil, fmt.Errorf("Not a number `%s`", rightStr)
				}
				rightVal = v
				right = &rightVal
			}

			if left != nil && right != nil && *left > 0 && *right > 0 && *left > *right {
				return nil, fmt.Errorf("Field left value cannot be greater than right value")
			}

			items = append(items, BoundItem{
				IsRange: true,
				Range: RangeBound{
					Start:    left,
					StartRaw: leftStr,
					End:      right,
					EndRaw:   rightStr,
					Fallback: fallbackVal,
				},
			})
		} else {
			// Single bound
			var idxStr string
			var fallbackVal *string
			if strings.Contains(part, "=") {
				eqIdx := strings.Index(part, "=")
				idxStr = part[:eqIdx]
				fb := part[eqIdx+1:]
				fallbackVal = &fb
			} else {
				idxStr = part
			}

			if idxStr == "0" || idxStr == "-0" {
				return nil, fmt.Errorf("Zero is not a valid field")
			}
			v, err := strconv.Atoi(idxStr)
			if err != nil {
				return nil, fmt.Errorf("Not a number `%s`", idxStr)
			}

			items = append(items, BoundItem{
				IsRange: false,
				Single: SingleBound{
					Idx:      v,
					Raw:      idxStr,
					Fallback: fallbackVal,
				},
			})
		}
	}
	return items, nil
}

func parseFormatString(raw string) (FormatString, error) {
	if !strings.Contains(raw, "{") && !strings.Contains(raw, "}") {
		items, err := parseUserBoundsList(raw)
		if err != nil {
			return FormatString{}, err
		}
		return FormatString{IsFormat: false, Plain: items}, nil
	}

	var parts []FormatPart
	var curLiteral strings.Builder
	i := 0
	for i < len(raw) {
		if raw[i] == '{' {
			if i+1 < len(raw) && raw[i+1] == '{' {
				curLiteral.WriteByte('{')
				i += 2
				continue
			}
			// Opening brace
			j := strings.IndexByte(raw[i+1:], '}')
			if j == -1 {
				return FormatString{}, fmt.Errorf("Field format error: missing closing parenthesis")
			}
			j += i + 1
			inner := raw[i+1 : j]
			if inner == "" {
				return FormatString{}, fmt.Errorf("Field format error: empty field")
			}
			items, err := parseUserBoundsList(inner)
			if err != nil {
				return FormatString{}, err
			}
			if curLiteral.Len() > 0 {
				parts = append(parts, FormatPart{IsPlaceholder: false, Literal: curLiteral.String()})
				curLiteral.Reset()
			}
			parts = append(parts, FormatPart{IsPlaceholder: true, Placeholder: BoundPlaceholder{Items: items}})
			i = j + 1
		} else if raw[i] == '}' {
			if i+1 < len(raw) && raw[i+1] == '}' {
				curLiteral.WriteByte('}')
				i += 2
				continue
			}
			return FormatString{}, fmt.Errorf("Field format error: missing opening parenthesis")
		} else {
			curLiteral.WriteByte(raw[i])
			i++
		}
	}
	if curLiteral.Len() > 0 {
		parts = append(parts, FormatPart{IsPlaceholder: false, Literal: curLiteral.String()})
	}
	return FormatString{IsFormat: true, Parts: parts}, nil
}

func printHelp() {
	term := os.Getenv("TERM")
	noColor := os.Getenv("NO_COLOR")
	isTTY := false
	if fi, err := os.Stdout.Stat(); err == nil && (fi.Mode()&os.ModeCharDevice) != 0 {
		isTTY = true
	}

	useColor := isTTY && term != "" && term != "dumb" && noColor == ""

	if useColor {
