	} else {
		fmt.Print("tuc 1.3.0\nCut text (or bytes) where a delimiter matches, then keep the desired parts.\n\nUSAGE:\n    tuc [FLAGS] [OPTIONS] < input\n    tuc [FLAGS] [OPTIONS] filepath\n\nFLAGS:\n    -g, --greedy-delimiter        Match consecutive delimiters as if it was one\n    -p, --compress-delimiter      Print only the first delimiter of a sequence\n    -s, --only-delimited          Print only lines containing the delimiter\n    -V, --version                 Print version information\n    -z, --zero-terminated         Line delimiter is NUL (\\0), not LF (\\n)\n    -h, --help                    Print this help and exit\n    -m, --complement              Invert fields (e.g. '2' becomes '1,3:')\n    -j, --(no-)join               Print selected parts with delimiter in between\n    --json                        Print fields as a JSON array of strings\n    --no-mmap                     Disable memory mapping\n\nOPTIONS:\n    -f, --fields <bounds>         Fields to keep, 1-indexed, comma separated.\n                                  Use colon (:) to match a range (inclusive).\n                                  Use equal (=) to apply out of bound fallback.\n                                  Fields can be negative (-1 is the last field).\n                                  [default: 1:]\n\n                                  e.g. cutting the string 'a-b-c-d' on '-'\n                                    -f 1     => a\n                                    -f 1:    => a-b-c-d\n                                    -f 1:3   => a-b-c\n                                    -f 3,2   => cb\n                                    -f 3,1:2 => ca-b\n                                    -f -3:-2 => b-c\n                                    -f 1,8=fallback => afallback\n\n                                  To re-apply the delimiter add -j, to replace\n                                  it add -r (followed by the new delimiter).\n\n                                  You can also format the output using {} syntax\n                                  e.g.\n                                    -f '({1}, {2})' => (a, b)\n\n                                  You can escape { and } using {{ and }}.\n\n    -b, --bytes <bounds>          Same as --fields, but it keeps bytes\n    -c, --characters <bounds>     Same as --fields, but it keeps characters\n    -l, --lines <bounds>          Same as --fields, but it keeps lines\n                                  Implies --join. To merge lines, use --no-join\n    -d, --delimiter <delimiter>   Delimiter used by --fields to cut the text\n                                  [default: \\t]\n    -e, --regex <some regex>      Use a regular expression as delimiter\n    -r, --replace-delimiter <new> Replace the delimiter with the provided text.\n                                  Implies --join\n    -t, --trim <type>             Trim the delimiter (greedy). Valid values are\n                                  (l|L)eft, (r|R)ight, (b|B)oth\n        --fallback-oob <fallback> Generic fallback output for any field that\n                                  cannot be found (oob stands for out of bound).\n                                  It's overridden by any fallback assigned to a\n                                  specific field (see -f for help)\n    -M, --fixed-memory <size>     Read the input in chunks of <size> kilobytes.\n                                  This allows to read lines arbitrarily large.\n                                  Works only with single-byte delimiters,\n                                  fields in ascending order, -z, -j, -r\n\nOptions precedence:\n    --trim and --compress-delimiter are applied before --fields or similar\n\nMemory consumption:\n    --characters and --fields read and allocate memory one line at a time\n\n    --lines allocate memory one line at a time as long as the requested fields\n    are ordered and non-negative (e.g. -l 1,3:4,4,7), otherwise it allocates\n    the whole input in memory (it also happens when -p or -m are being used)\n\n    --bytes allocate the whole input in memory\n\n    --fixed-memory will read the input in chunks of <size> kilobytes. This\n    allows to read lines arbitrarily large. Works only with single-byte\n    delimiters, fields in ascending order, -z, -j, -r\n\nColors:\n    Help is displayed using colors. Colors will be suppressed in the\n    following circumstances:\n    - when the TERM environment variable is not set or set to \"dumb\"\n    - when the NO_COLOR environment variable is set (regardless of value)\n")
	}
}

func parseCLI(args []string) (Config, error) {
	// Check --help / -h
	for _, arg := range args {
		if arg == "-h" || arg == "--help" {
			printHelp()
			os.Exit(0)
		}
		if arg == "-V" || arg == "--version" {
			fmt.Println("tuc 1.3.0")
			os.Exit(0)
		}
	}

	cfg := Config{
		Mode:      ModeFields,
		Delimiter: "\t",
	}

	modeBoundsRaw := map[Mode]string{
		ModeFields: "1:",
	}
	lastMode := ModeFields

	setFlags := make(map[string]bool)
	var unexpected []string

	i := 0
	for i < len(args) {
		arg := args[i]
		if arg == "--" {
			i++
			for i < len(args) {
				if cfg.FilePath == "" {
					cfg.FilePath = args[i]
				} else {
					unexpected = append(unexpected, args[i])
				}
				i++
			}
			break
		}

		if strings.HasPrefix(arg, "--") {
			optName := arg
			var optVal string
			hasVal := false
			if strings.Contains(arg, "=") {
				parts := strings.SplitN(arg, "=", 2)
				optName = parts[0]
				optVal = parts[1]
				hasVal = true
			}

			switch optName {
			case "--fields", "--bytes", "--characters", "--lines", "--delimiter", "--regex", "--replace-delimiter", "--trim", "--fallback-oob", "--fixed-memory":
				if setFlags[optName] {
					unexpected = append(unexpected, arg)
					if !hasVal && i+1 < len(args) && !strings.HasPrefix(args[i+1], "-") {
						unexpected = append(unexpected, args[i+1])
						i++
					}
					i++
					continue
				}
				setFlags[optName] = true
				val := optVal
				if !hasVal {
					if i+1 < len(args) {
						val = args[i+1]
						i++
					} else {
						if optName == "--fallback-oob" {
							unexpected = append(unexpected, arg)
							i++
							continue
						}
						return cfg, fmt.Errorf("the '%s' option doesn't have an associated value", optName)
					}
				} else if val == "" {
					return cfg, fmt.Errorf("the '%s' option doesn't have an associated value", optName)
				}

				switch optName {
				case "--fields":
					modeBoundsRaw[ModeFields] = val
					lastMode = ModeFields
				case "--bytes":
					modeBoundsRaw[ModeBytes] = val
					lastMode = ModeBytes
				case "--characters":
					modeBoundsRaw[ModeCharacters] = val
					lastMode = ModeCharacters
				case "--lines":
					modeBoundsRaw[ModeLines] = val
					lastMode = ModeLines
				case "--delimiter":
					cfg.Delimiter = val
					cfg.DelimiterSet = true
				case "--regex":
					cfg.RegexStr = val
				case "--replace-delimiter":
					cfg.Replace = &val
				case "--trim":
					cfg.Trim = val
				case "--fallback-oob":
					cfg.FallbackOOB = &val
				case "--fixed-memory":
					cfg.FixedMemory = -1 // marked as set
					v, err := strconv.Atoi(val)
					if err != nil {
						return cfg, fmt.Errorf("failed to parse '%s': invalid digit found in string", val)
					}
					if v == 0 {
						return cfg, fmt.Errorf("tuc: runtime error. --fixed-memory cannot be 0")
					}
					cfg.FixedMemory = v
				}

			case "--greedy-delimiter", "--compress-delimiter", "--only-delimited", "--zero-terminated", "--complement", "--join", "--no-join", "--json", "--no-mmap":
				if setFlags[optName] {
					unexpected = append(unexpected, arg)
					i++
					continue
				}
				setFlags[optName] = true

				switch optName {
				case "--greedy-delimiter":
					cfg.Greedy = true
				case "--compress-delimiter":
					cfg.Compress = true
				case "--only-delimited":
					cfg.OnlyDelimited = true
				case "--zero-terminated":
					cfg.ZeroTerminated = true
				case "--complement":
					cfg.Complement = true
				case "--join":
					cfg.Join = true
					cfg.JoinSet = true
				case "--no-join":
					cfg.NoJoin = true
					cfg.NoJoinSet = true
				case "--json":
					cfg.JSON = true
				case "--no-mmap":
					cfg.NoMmap = true
				}

			default:
				unexpected = append(unexpected, arg)
			}
			i++
		} else if strings.HasPrefix(arg, "-") && arg != "-" {
			// Short options / flags
			if setFlags[arg] {
				unexpected = append(unexpected, arg)
				i++
				continue
			}

			// Check if arg starts with a short option taking a value
			char := arg[1:2]
			switch char {
			case "f", "b", "c", "l", "d", "e", "r", "t", "M":
				optKey := "-" + char
				if setFlags[optKey] {
					unexpected = append(unexpected, arg)
					i++
					continue
				}
				setFlags[optKey] = true
				var val string
				if len(arg) > 2 {
					val = arg[2:]
				} else if i+1 < len(args) {
					val = args[i+1]
					i++
				} else {
					return cfg, fmt.Errorf("the '%s' option doesn't have an associated value", optKey)
				}

				switch char {
				case "f":
					modeBoundsRaw[ModeFields] = val
					lastMode = ModeFields
				case "b":
					modeBoundsRaw[ModeBytes] = val
					lastMode = ModeBytes
				case "c":
					modeBoundsRaw[ModeCharacters] = val
					lastMode = ModeCharacters
				case "l":
					modeBoundsRaw[ModeLines] = val
					lastMode = ModeLines
				case "d":
					cfg.Delimiter = val
					cfg.DelimiterSet = true
				case "e":
					cfg.RegexStr = val
				case "r":
					cfg.Replace = &val
				case "t":
					cfg.Trim = val
				case "M":
					v, err := strconv.Atoi(val)
					if err != nil {
						return cfg, fmt.Errorf("failed to parse '%s': invalid digit found in string", val)
					}
					if v == 0 {
						return cfg, fmt.Errorf("tuc: runtime error. --fixed-memory cannot be 0")
					}
					cfg.FixedMemory = v
				}

			default:
				// Boolean flags sequence
				allValid := true
				for j := 1; j < len(arg); j++ {
					c := string(arg[j])
					switch c {
					case "g", "p", "s", "z", "m", "j":
						fKey := "-" + c
						if setFlags[fKey] {
							allValid = false
							break
						}
						setFlags[fKey] = true
						switch c {
						case "g":
							cfg.Greedy = true
						case "p":
							cfg.Compress = true
						case "s":
							cfg.OnlyDelimited = true
						case "z":
							cfg.ZeroTerminated = true
						case "m":
							cfg.Complement = true
						case "j":
							cfg.Join = true
							cfg.JoinSet = true
						}
					default:
						allValid = false
						break
					}
					if !allValid {
						break
					}
				}
				if !allValid {
					unexpected = append(unexpected, arg)
				}
			}
			i++
		} else {
			// Positional argument
			if cfg.FilePath == "" {
				cfg.FilePath = arg
			} else {
				unexpected = append(unexpected, arg)
			}
			i++
		}
	}

	if len(unexpected) > 0 {
		unjson, _ := json.Marshal(unexpected)
		return cfg, fmt.Errorf("tuc: unexpected arguments: %s\nTry 'tuc --help' for more information.", string(unjson))
	}

	cfg.Mode = lastMode
	cfg.BoundsRaw = modeBoundsRaw[lastMode]

	// Validate trim if set
	if cfg.Trim != "" {
		t := cfg.Trim
		if t != "l" && t != "L" && t != "r" && t != "R" && t != "b" && t != "B" {
			return cfg, fmt.Errorf("failed to parse '%s': Valid trim values are (l|L)eft, (r|R)ight, (b|B)oth", cfg.Trim)
		}
	}

	// Parse bounds
	fmtBounds, err := parseFormatString(cfg.BoundsRaw)
	if err != nil {
		return cfg, fmt.Errorf("failed to parse '%s': %v", cfg.BoundsRaw, err)
	}
	cfg.Bounds = fmtBounds

	// Validate mode conflicts and combinations
	if cfg.Join && cfg.NoJoin {
		return cfg, fmt.Errorf("tuc: runtime error. It's not possible to use --join and --no-join simultaneously")
	}
	if cfg.Mode == ModeCharacters && cfg.NoJoin {
		return cfg, fmt.Errorf("tuc: runtime error. Since --characters implies --join, you can't pass --no-join")
	}
	if cfg.Replace != nil && cfg.NoJoin {
		return cfg, fmt.Errorf("tuc: runtime error. You can't pass --no-join when using --replace, which implies --join")
	}
	if cfg.JSON && cfg.NoJoin {
		return cfg, fmt.Errorf("tuc: runtime error. Using both --json and --no-join is not permitted")
	}
	if cfg.JSON && (cfg.Mode == ModeBytes || cfg.Mode == ModeLines) {
		return cfg, fmt.Errorf("tuc: runtime error. --json support is available only for --fields and --characters")
	}
	if cfg.JSON && cfg.Replace != nil {
		return cfg, fmt.Errorf("tuc: runtime error. The use of --replace with --json is not supported")
	}
	if cfg.JSON && cfg.Bounds.IsFormat {
		return cfg, fmt.Errorf("tuc: runtime error. Cannot format fields when using --json")
	}

	if cfg.RegexStr != "" {
		re, err := regexp.Compile(cfg.RegexStr)
		if err != nil {
			return cfg, fmt.Errorf("tuc: runtime error. The regular expression is malformed. %v", err)
		}
		cfg.Regex = re

		if (cfg.Join || cfg.Mode == ModeLines) && cfg.Replace == nil {
			return cfg, fmt.Errorf("tuc: runtime error. Cannot use --regex and --join without --replace-delimiter")
		}
		if cfg.Compress && cfg.Replace == nil {
			return cfg, fmt.Errorf("tuc: runtime error. Cannot use --regex and --compress-delimiter without --replace-delimiter")
		}
	}

	if cfg.Compress && (cfg.Mode == ModeBytes || cfg.Mode == ModeCharacters) {
		return cfg, fmt.Errorf("tuc: runtime error. Delimiters can be compressed only with --fields and --lines")
	}

	if cfg.FixedMemory > 0 {
		if cfg.Greedy || cfg.Compress || cfg.OnlyDelimited || cfg.Complement || cfg.Mode != ModeFields || cfg.Regex != nil || cfg.Trim != "" || cfg.JSON {
			return cfg, fmt.Errorf("tuc: runtime error. StreamOpt supports solely forward fields, join and single-character delimiters")
		}
		if len(cfg.Delimiter) != 1 {
			return cfg, fmt.Errorf("tuc: runtime error. Delimiter must be 1 byte wide for FastOpt")
		}
	}

	return cfg, nil
}

func main() {
	cfg, err := parseCLI(os.Args[1:])
	if err != nil {
		fmt.Fprintln(os.Stderr, err.Error())
		os.Stdout.Sync()
		os.Stderr.Sync()
		os.Exit(1)
	}

	// Open input
	var input io.Reader
	if cfg.FilePath != "" {
		fi, err := os.Stat(cfg.FilePath)
		if os.IsNotExist(err) {
			fmt.Fprintf(os.Stderr, "tuc: runtime error. The file \"%s\" does not exist\n", cfg.FilePath)
			os.Stdout.Sync()
			os.Stderr.Sync()
			os.Exit(1)
		}
		if err != nil || !fi.Mode().IsRegular() {
			fmt.Fprintf(os.Stderr, "tuc: runtime error. The path \"%s\" is not a file\n", cfg.FilePath)
			os.Stdout.Sync()
			os.Stderr.Sync()
			os.Exit(1)
		}
		f, err := os.Open(cfg.FilePath)
		if err != nil {
			fmt.Fprintf(os.Stderr, "tuc: runtime error. The file \"%s\" does not exist\n", cfg.FilePath)
			os.Stdout.Sync()
			os.Stderr.Sync()
			os.Exit(1)
		}
		defer f.Close()
		input = f
	} else {
		input = os.Stdin
	}

	err = run(cfg, input)
	if err != nil {
		fmt.Fprintln(os.Stderr, err.Error())
		os.Stdout.Sync()
		os.Stderr.Sync()
		os.Exit(1)
	}
	os.Stdout.Sync()
	os.Stderr.Sync()
}

func resolveIdx(idx int, N int) int {
	if idx > 0 {
		return idx - 1
	}
	if idx < 0 {
		return N + idx
	}
	return -1
}

type EvalResult struct {
	Items        []string
	JoinedBySelf bool
}

func evalBoundItem(item BoundItem, items []string, globalFallback *string, complement bool, isStrictRangeEnd bool, rangeJoinDelim string) (EvalResult, error) {
	N := len(items)
	if complement {
		if !item.IsRange {
			pos := resolveIdx(item.Single.Idx, N)
			if pos < 0 || pos >= N {
				res := make([]string, N)
				copy(res, items)
				return EvalResult{Items: res}, nil
			}
			var res []string
			res = append(res, items[:pos]...)
			res = append(res, items[pos+1:]...)
			return EvalResult{Items: res}, nil
		} else {
			startVal := 1
			if item.Range.Start != nil {
				startVal = *item.Range.Start
			}
			endVal := -1
			if item.Range.End != nil {
				endVal = *item.Range.End
			}
			resA := resolveIdx(startVal, N)
			resB := resolveIdx(endVal, N)
			if resA > resB {
				return EvalResult{}, fmt.Errorf("Error: Field left value cannot be greater than right value")
			}
			if resA >= N || resB < 0 || resA > resB {
				res := make([]string, N)
				copy(res, items)
				return EvalResult{Items: res}, nil
			}
			sPos := resA
			if sPos < 0 {
				sPos = 0
			}
			ePos := resB
			if ePos >= N {
				ePos = N - 1
			}
			if sPos > ePos {
				res := make([]string, N)
				copy(res, items)
				return EvalResult{Items: res}, nil
			}
			var res []string
			res = append(res, items[:sPos]...)
			res = append(res, items[ePos+1:]...)
			return EvalResult{Items: res}, nil
		}
	}

	if !item.IsRange {
		pos := resolveIdx(item.Single.Idx, N)
		if pos < 0 || pos >= N {
			if item.Single.Fallback != nil {
				return EvalResult{Items: []string{*item.Single.Fallback}}, nil
			}
			if globalFallback != nil {
				return EvalResult{Items: []string{*globalFallback}}, nil
			}
			return EvalResult{}, fmt.Errorf("Error: Out of bounds: %d", item.Single.Idx)
		}
		return EvalResult{Items: []string{items[pos]}}, nil
	} else {
		startVal := 1
		if item.Range.Start != nil {
			startVal = *item.Range.Start
		}
		endVal := -1
		if item.Range.End != nil {
			endVal = *item.Range.End
		}
		resA := resolveIdx(startVal, N)
		resB := resolveIdx(endVal, N)
		if resA > resB {
			return EvalResult{}, fmt.Errorf("Error: Field left value cannot be greater than right value")
		}

		if (isStrictRangeEnd || item.Range.Start != nil || item.Range.End != nil) && resA < 0 {
			if item.Range.Fallback != nil {
				return EvalResult{Items: []string{*item.Range.Fallback}}, nil
			}
			if globalFallback != nil {
				return EvalResult{Items: []string{*globalFallback}}, nil
			}
			return EvalResult{}, fmt.Errorf("Error: Out of bounds: %d", startVal)
		}

		if isStrictRangeEnd && item.Range.End != nil && resB >= N {
			if item.Range.Fallback != nil {
				return EvalResult{Items: []string{*item.Range.Fallback}}, nil
			}
			if globalFallback != nil {
				return EvalResult{Items: []string{*globalFallback}}, nil
			}
			return EvalResult{}, fmt.Errorf("Error: Out of bounds: %d", endVal)
		}

		sPos := resA
		if sPos < 0 {
			sPos = 0
		}
		ePos := resB
		if ePos >= N {
			ePos = N - 1
		}

		if sPos <= ePos && resA < N && resB >= 0 {
			sub := items[sPos : ePos+1]
			if rangeJoinDelim != "" {
				joined := strings.Join(sub, rangeJoinDelim)
				return EvalResult{Items: []string{joined}, JoinedBySelf: true}, nil
			} else {
				res := make([]string, len(sub))
				copy(res, sub)
				return EvalResult{Items: res}, nil
			}
		} else {
			if item.Range.Fallback != nil {
				return EvalResult{Items: []string{*item.Range.Fallback}}, nil
			}
			if globalFallback != nil {
				return EvalResult{Items: []string{*globalFallback}}, nil
			}
			oobIdx := startVal
			if resA >= N {
				oobIdx = startVal
			} else if resB < 0 {
				oobIdx = endVal
			}
			return EvalResult{}, fmt.Errorf("Error: Out of bounds: %d", oobIdx)
		}
	}
}

func run(cfg Config, input io.Reader) error {
	lineDelim := byte('\n')
	if cfg.ZeroTerminated {
		lineDelim = 0
	}

	strictRangeEnd := cfg.Greedy || cfg.Regex != nil || cfg.Compress

	switch cfg.Mode {
	case ModeBytes:
		data, err := io.ReadAll(input)
		if err != nil {
			return err
		}
		if len(data) == 0 {
			return nil
		}

		// Trim if set
		if cfg.Trim != "" {
			t := cfg.Trim
			delim := cfg.Delimiter
			if delim != "" {
				s := string(data)
				if t == "l" || t == "L" || t == "b" || t == "B" {
					for strings.HasPrefix(s, delim) {
						s = s[len(delim):]
					}
				}
				if t == "r" || t == "R" || t == "b" || t == "B" {
					for strings.HasSuffix(s, delim) {
						s = s[:len(s)-len(delim)]
					}
				}
				data = []byte(s)
			}
		}

		items := make([]string, len(data))
		for i, b := range data {
			items[i] = string([]byte{b})
		}

		boundItems := cfg.Bounds.Plain
		if cfg.Bounds.IsFormat {
			var outStr strings.Builder
			for _, part := range cfg.Bounds.Parts {
				if part.IsPlaceholder {
					var pSel []string
					for _, bItem := range part.Placeholder.Items {
						res, err := evalBoundItem(bItem, items, cfg.FallbackOOB, cfg.Complement, strictRangeEnd, "")
						if err != nil {
							os.Stdout.WriteString(outStr.String())
							os.Stdout.Sync()
							return err
						}
						pSel = append(pSel, res.Items...)
					}
					joinDelim := ""
					if cfg.Replace != nil {
						joinDelim = *cfg.Replace
					}
					outStr.WriteString(strings.Join(pSel, joinDelim))
				} else {
					outStr.WriteString(part.Literal)
				}
			}
			os.Stdout.WriteString(outStr.String())
			return nil
		} else {
			joinDelim := ""
			if cfg.Replace != nil {
				joinDelim = *cfg.Replace
			}
			for idx, bItem := range boundItems {
				if idx > 0 {
					os.Stdout.WriteString(joinDelim)
				}
				res, err := evalBoundItem(bItem, items, cfg.FallbackOOB, cfg.Complement, strictRangeEnd, "")
				if err != nil {
					os.Stdout.Sync()
					return err
				}
				os.Stdout.WriteString(strings.Join(res.Items, joinDelim))
			}
			return nil
		}

	case ModeCharacters:
		reader := bufio.NewReader(input)
		for {
			line, err := reader.ReadString(lineDelim)
			if len(line) == 0 && err != nil {
				break
			}
			lineContent := strings.TrimSuffix(line, string([]byte{lineDelim}))

			if cfg.Trim != "" {
				t := cfg.Trim
				delim := cfg.Delimiter
				if delim != "" {
					if t == "l" || t == "L" || t == "b" || t == "B" {
						for strings.HasPrefix(lineContent, delim) {
							lineContent = lineContent[len(delim):]
						}
					}
					if t == "r" || t == "R" || t == "b" || t == "B" {
						for strings.HasSuffix(lineContent, delim) {
							lineContent = lineContent[:len(lineContent)-len(delim)]
						}
					}
				}
			}

			runes := []rune(lineContent)
			items := make([]string, len(runes))
			for i, r := range runes {
				items[i] = string(r)
			}

			if cfg.Bounds.IsFormat {
				var outStr strings.Builder
				for _, part := range cfg.Bounds.Parts {
					if part.IsPlaceholder {
						var pSel []string
						for _, bItem := range part.Placeholder.Items {
							res, err := evalBoundItem(bItem, items, cfg.FallbackOOB, cfg.Complement, strictRangeEnd, "")
							if err != nil {
								os.Stdout.WriteString(outStr.String())
								os.Stdout.Sync()
								return err
							}
							pSel = append(pSel, res.Items...)
						}
						joinDelim := ""
						if cfg.Replace != nil {
							joinDelim = *cfg.Replace
						}
						outStr.WriteString(strings.Join(pSel, joinDelim))
					} else {
						outStr.WriteString(part.Literal)
					}
				}
				os.Stdout.WriteString(outStr.String())
				os.Stdout.Write([]byte{lineDelim})
			} else {
				if cfg.JSON {
					var selected []string
					for _, bItem := range cfg.Bounds.Plain {
						res, err := evalBoundItem(bItem, items, cfg.FallbackOOB, cfg.Complement, strictRangeEnd, "")
						if err != nil {
							if len(selected) > 0 {
								os.Stdout.WriteString("[\"" + strings.Join(selected, "\",\"") + "\",")
							}
							os.Stdout.Sync()
							return err
						}
						selected = append(selected, res.Items...)
					}
					b, _ := json.Marshal(selected)
					os.Stdout.Write(b)
					os.Stdout.Write([]byte{'\n'})
				} else {
					joinDelim := ""
					if cfg.Replace != nil {
						joinDelim = *cfg.Replace
					}
					for idx, bItem := range cfg.Bounds.Plain {
						if idx > 0 {
							os.Stdout.WriteString(joinDelim)
						}
						res, err := evalBoundItem(bItem, items, cfg.FallbackOOB, cfg.Complement, strictRangeEnd, "")
						if err != nil {
							os.Stdout.Sync()
							return err
						}
						os.Stdout.WriteString(strings.Join(res.Items, joinDelim))
					}
					os.Stdout.Write([]byte{lineDelim})
				}
			}

			if err != nil {
				break
			}
		}

	case ModeLines:
		var lines []string
		reader := bufio.NewReader(input)
		for {
			line, err := reader.ReadString(lineDelim)
			if len(line) == 0 && err != nil {
				break
			}
			lines = append(lines, strings.TrimSuffix(line, string([]byte{lineDelim})))
			if err != nil {
				break
			}
		}

		if len(lines) == 0 {
			return nil
		}

		if cfg.Compress {
			var comp []string
			for _, l := range lines {
				if l == "" && len(comp) > 0 && comp[len(comp)-1] == "" {
					continue
				}
				comp = append(comp, l)
			}
			lines = comp
		}

		if cfg.Trim != "" {
			t := cfg.Trim
			if t == "l" || t == "L" || t == "b" || t == "B" {
				for len(lines) > 0 && lines[0] == "" {
					lines = lines[1:]
				}
			}
			if t == "r" || t == "R" || t == "b" || t == "B" {
				for len(lines) > 0 && lines[len(lines)-1] == "" {
					lines = lines[:len(lines)-1]
				}
			}
		}

		if cfg.Bounds.IsFormat {
			var outStr strings.Builder
			for _, part := range cfg.Bounds.Parts {
				if part.IsPlaceholder {
					var pSel []string
					for _, bItem := range part.Placeholder.Items {
						res, err := evalBoundItem(bItem, lines, cfg.FallbackOOB, cfg.Complement, strictRangeEnd, "")
						if err != nil {
							os.Stdout.WriteString(outStr.String())
							os.Stdout.Sync()
							return err
						}
						pSel = append(pSel, res.Items...)
					}
					joinDelim := string([]byte{lineDelim})
					if cfg.NoJoin {
						joinDelim = ""
					}
					if cfg.Replace != nil {
						joinDelim = *cfg.Replace
					}
					outStr.WriteString(strings.Join(pSel, joinDelim))
				} else {
					outStr.WriteString(part.Literal)
				}
			}
			os.Stdout.WriteString(outStr.String())
			os.Stdout.Write([]byte{lineDelim})
		} else {
			joinDelim := string([]byte{lineDelim})
			if cfg.NoJoin {
				joinDelim = ""
			}
			if cfg.Replace != nil {
				joinDelim = *cfg.Replace
			}

			for idx, bItem := range cfg.Bounds.Plain {
				if idx > 0 {
					os.Stdout.WriteString(joinDelim)
				}
				res, err := evalBoundItem(bItem, lines, cfg.FallbackOOB, cfg.Complement, strictRangeEnd, "")
				if err != nil {
					os.Stdout.Sync()
					return err
				}
				os.Stdout.WriteString(strings.Join(res.Items, joinDelim))
			}
			os.Stdout.Write([]byte{lineDelim})
		}

	case ModeFields:
		reader := bufio.NewReader(input)
		for {
			line, err := reader.ReadString(lineDelim)
			if len(line) == 0 && err != nil {
				break
			}
			lineContent := strings.TrimSuffix(line, string([]byte{lineDelim}))

			// Trim
			if cfg.Trim != "" {
				t := cfg.Trim
				delim := cfg.Delimiter
				if cfg.Regex == nil && delim != "" {
					if t == "l" || t == "L" || t == "b" || t == "B" {
						for strings.HasPrefix(lineContent, delim) {
							lineContent = lineContent[len(delim):]
						}
					}
					if t == "r" || t == "R" || t == "b" || t == "B" {
						for strings.HasSuffix(lineContent, delim) {
							lineContent = lineContent[:len(lineContent)-len(delim)]
						}
					}
				}
			}

			// Compress
			if cfg.Compress && cfg.Regex == nil && cfg.Delimiter != "" {
				d := cfg.Delimiter
				d2 := d + d
				for strings.Contains(lineContent, d2) {
					lineContent = strings.ReplaceAll(lineContent, d2, d)
				}
			}

			// Check only delimited
			if cfg.OnlyDelimited {
				if cfg.Regex != nil {
					if !cfg.Regex.MatchString(lineContent) {
						if err != nil {
							break
						}
						continue
					}
				} else {
					if !strings.Contains(lineContent, cfg.Delimiter) {
						if err != nil {
							break
						}
						continue
					}
				}
			}

			// Split fields
			var fields []string
			var origDelims []string

			if cfg.Regex != nil {
				locs := cfg.Regex.FindAllStringIndex(lineContent, -1)
				lastIdx := 0
				for _, loc := range locs {
					fields = append(fields, lineContent[lastIdx:loc[0]])
					origDelims = append(origDelims, lineContent[loc[0]:loc[1]])
					lastIdx = loc[1]
				}
				fields = append(fields, lineContent[lastIdx:])
			} else if cfg.Delimiter == "" {
				// Empty delimiter: splits into ["", "c1", "c2", ..., ""]
				runes := []rune(lineContent)
				fields = make([]string, len(runes)+2)
				fields[0] = ""
				for idx, r := range runes {
					fields[idx+1] = string(r)
				}
				fields[len(fields)-1] = ""
				origDelims = make([]string, len(fields)-1)
			} else if cfg.Greedy {
				// Greedy split on consecutive delimiters
				s := lineContent
				d := cfg.Delimiter
				var f []string
				var del []string
				cur := 0
				for cur < len(s) {
					if strings.HasPrefix(s[cur:], d) {
						// match consecutive
						start := cur
						for cur < len(s) && strings.HasPrefix(s[cur:], d) {
							cur += len(d)
						}
						del = append(del, s[start:cur])
						f = append(f, "") // mark field boundary
					} else {
						if len(f) == 0 {
							f = append(f, "")
						}
						f[len(f)-1] += string(s[cur])
						cur++
					}
				}
				if len(del) > 0 && len(f) == len(del) {
					f = append(f, "")
				}
				if len(f) == 0 {
					f = []string{""}
				}
				fields = f
				origDelims = del
			} else {
				fields = strings.Split(lineContent, cfg.Delimiter)
				origDelims = make([]string, len(fields)-1)
				for i := range origDelims {
					origDelims[i] = cfg.Delimiter
				}
			}

			rangeJoinDelim := ""
			if cfg.Replace != nil {
				rangeJoinDelim = *cfg.Replace
			} else {
				rangeJoinDelim = cfg.Delimiter
			}

			if cfg.Bounds.IsFormat {
				var outStr strings.Builder
				for _, part := range cfg.Bounds.Parts {
					if part.IsPlaceholder {
						var pSel []string
						for _, bItem := range part.Placeholder.Items {
							res, err := evalBoundItem(bItem, fields, cfg.FallbackOOB, cfg.Complement, strictRangeEnd, rangeJoinDelim)
							if err != nil {
								os.Stdout.WriteString(outStr.String())
								os.Stdout.Sync()
								return err
							}
							pSel = append(pSel, res.Items...)
						}
						joinDelim := ""
						if cfg.Replace != nil {
							joinDelim = *cfg.Replace
						} else if cfg.Join {
							joinDelim = cfg.Delimiter
						}
						outStr.WriteString(strings.Join(pSel, joinDelim))
					} else {
						outStr.WriteString(part.Literal)
					}
				}
				os.Stdout.WriteString(outStr.String())
				os.Stdout.Write([]byte{lineDelim})
			} else {
				if cfg.JSON {
					var selected []string
					for _, bItem := range cfg.Bounds.Plain {
						res, err := evalBoundItem(bItem, fields, cfg.FallbackOOB, cfg.Complement, strictRangeEnd, "")
						if err != nil {
							if len(selected) > 0 {
								os.Stdout.WriteString("[\"" + strings.Join(selected, "\",\"") + "\",")
							}
							os.Stdout.Sync()
							return err
						}
						selected = append(selected, res.Items...)
					}
					b, _ := json.Marshal(selected)
					os.Stdout.Write(b)
					os.Stdout.Write([]byte{'\n'})
				} else {
					itemJoinDelim := ""
					if cfg.Replace != nil {
						itemJoinDelim = *cfg.Replace
					} else if cfg.Join {
						itemJoinDelim = cfg.Delimiter
					}

					for idx, bItem := range cfg.Bounds.Plain {
						rDelim := rangeJoinDelim
						if !cfg.Join && cfg.Replace == nil {
							rDelim = cfg.Delimiter
						}
						if idx > 0 {
							os.Stdout.WriteString(itemJoinDelim)
						}

						res, err := evalBoundItem(bItem, fields, cfg.FallbackOOB, cfg.Complement, strictRangeEnd, rDelim)
						if err != nil {
							os.Stdout.Sync()
							return err
						}

						if cfg.Join && cfg.Greedy && bItem.IsRange && !cfg.Complement {
							startVal := 1
							if bItem.Range.Start != nil {
								startVal = *bItem.Range.Start
							}
							endVal := -1
							if bItem.Range.End != nil {
								endVal = *bItem.Range.End
							}
							sPos := resolveIdx(startVal, len(fields))
							ePos := resolveIdx(endVal, len(fields))
							if sPos < 0 {
								sPos = 0
							}
							if ePos >= len(fields) {
								ePos = len(fields) - 1
							}
							if sPos <= ePos && sPos < len(fields) && ePos >= 0 {
								var sb strings.Builder
								for fIdx := sPos; fIdx <= ePos; fIdx++ {
									sb.WriteString(fields[fIdx])
									if fIdx < ePos && fIdx < len(origDelims) {
										sb.WriteString(origDelims[fIdx])
									}
								}
								os.Stdout.WriteString(sb.String())
							} else {
								os.Stdout.WriteString(strings.Join(res.Items, itemJoinDelim))
							}
						} else {
							os.Stdout.WriteString(strings.Join(res.Items, itemJoinDelim))
						}
					}
					os.Stdout.Write([]byte{lineDelim})
				}
			}

			if err != nil {
				break
			}
		}
	}

	return nil
}
