actions.command:
cat <<'EOF' > main.go
package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"regexp"
	"strconv"
	"strings"
)

type Mode int

const (
	ModeFields Mode = iota
	ModeBytes
	ModeCharacters
	ModeLines
)

type SingleBound struct {
	Idx      int
	Raw      string
	Fallback *string
}

type RangeBound struct {
	Start    *int
	StartRaw string
	End      *int
	EndRaw   string
	Fallback *string
}

type BoundItem struct {
	IsRange bool
	Single  SingleBound
	Range   RangeBound
}

type BoundPlaceholder struct {
	Items []BoundItem
}

type FormatPart struct {
	IsPlaceholder bool
	Literal       string
	Placeholder   BoundPlaceholder
}

type FormatString struct {
	IsFormat bool
	Parts    []FormatPart
	Plain    []BoundItem
}

type Config struct {
	Mode            Mode
	Bounds          FormatString
	BoundsRaw       string
	Delimiter       string
	DelimiterSet    bool
	Greedy          bool
	Compress        bool
	OnlyDelimited   bool
	ZeroTerminated  bool
	Complement      bool
	Join            bool
	JoinSet         bool
	NoJoin          bool
	NoJoinSet       bool
	JSON            bool
	NoMmap          bool
	RegexStr        string
	Regex           *regexp.Regexp
	Replace         *string
	Trim            string
	FallbackOOB     *string
	FixedMemory     int
	FilePath        string
}

func parseUserBoundsList(raw string) ([]BoundItem, error) {
	if raw == "" {
		return nil, fmt.Errorf("UserBoundsList must contain at least one UserBounds")
	}
	parts := strings.Split(raw, ",")
	var items []BoundItem
	for _, part := range parts {
		if part == "" {
			return nil, fmt.Errorf("Field format error: empty field")
		}
		if strings.Contains(part, ":") {
			// Range bound
			var rangeSpec string
			var fallbackVal *string
			if strings.Contains(part, "=") {
				eqIdx := strings.Index(part, "=")
				rangeSpec = part[:eqIdx]
				fb := part[eqIdx+1:]
				fallbackVal = &fb
			} else {
				rangeSpec = part
			}

			if rangeSpec == ":" {
				return nil, fmt.Errorf("Field format error, no numbers next to `:`")
			}

			colonIdx := strings.Index(rangeSpec, ":")
			leftStr := rangeSpec[:colonIdx]
			rightStr := rangeSpec[colonIdx+1:]

			var left *int
			var leftVal int
			if leftStr != "" {
				if leftStr == "0" || leftStr == "-0" {
					return nil, fmt.Errorf("Zero is not a valid field")
				}
				v, err := strconv.Atoi(leftStr)
				if err != nil {
					return nil, fmt.Errorf("Not a number `%s`", leftStr)
				}
				leftVal = v
				left = &leftVal
			}

			var right *int
			var rightVal int
			if rightStr != "" {
				if rightStr == "0" || rightStr == "-0" {
					return nil, fmt.Errorf("Zero is not a valid field")
				}
				v, err := strconv.Atoi(rightStr)
				if err != nil {
					return nil, fmt.Errorf("Not a number `%s`", rightStr)
				}
				rightVal = v
				right = &rightVal
			}

			if left != nil && right != nil && *left > 0 && *right > 0 && *left > *right {
				return nil, fmt.Errorf("Field left value cannot be greater than right value")
			}

			items = append(items, BoundItem{
				IsRange: true,
				Range: RangeBound{
					Start:    left,
					StartRaw: leftStr,
					End:      right,
					EndRaw:   rightStr,
					Fallback: fallbackVal,
				},
			})
		} else {
			// Single bound
			var idxStr string
			var fallbackVal *string
			if strings.Contains(part, "=") {
				eqIdx := strings.Index(part, "=")
				idxStr = part[:eqIdx]
				fb := part[eqIdx+1:]
				fallbackVal = &fb
			} else {
				idxStr = part
			}

			if idxStr == "0" || idxStr == "-0" {
				return nil, fmt.Errorf("Zero is not a valid field")
			}
			v, err := strconv.Atoi(idxStr)
			if err != nil {
				return nil, fmt.Errorf("Not a number `%s`", idxStr)
			}

			items = append(items, BoundItem{
				IsRange: false,
				Single: SingleBound{
					Idx:      v,
					Raw:      idxStr,
					Fallback: fallbackVal,
				},
			})
		}
	}
	return items, nil
}

func parseFormatString(raw string) (FormatString, error) {
	if !strings.Contains(raw, "{") && !strings.Contains(raw, "}") {
		items, err := parseUserBoundsList(raw)
		if err != nil {
			return FormatString{}, err
		}
		return FormatString{IsFormat: false, Plain: items}, nil
	}

	var parts []FormatPart
	var curLiteral strings.Builder
	i := 0
	for i < len(raw) {
		if raw[i] == '{' {
			if i+1 < len(raw) && raw[i+1] == '{' {
				curLiteral.WriteByte('{')
				i += 2
				continue
			}
			// Opening brace
			j := strings.IndexByte(raw[i+1:], '}')
			if j == -1 {
				return FormatString{}, fmt.Errorf("Field format error: missing closing parenthesis")
			}
			j += i + 1
			inner := raw[i+1 : j]
			if inner == "" {
				return FormatString{}, fmt.Errorf("Field format error: empty field")
			}
			items, err := parseUserBoundsList(inner)
			if err != nil {
				return FormatString{}, err
			}
			if curLiteral.Len() > 0 {
				parts = append(parts, FormatPart{IsPlaceholder: false, Literal: curLiteral.String()})
				curLiteral.Reset()
			}
			parts = append(parts, FormatPart{IsPlaceholder: true, Placeholder: BoundPlaceholder{Items: items}})
			i = j + 1
		} else if raw[i] == '}' {
			if i+1 < len(raw) && raw[i+1] == '}' {
				curLiteral.WriteByte('}')
				i += 2
				continue
			}
			return FormatString{}, fmt.Errorf("Field format error: missing opening parenthesis")
		} else {
			curLiteral.WriteByte(raw[i])
			i++
		}
	}
	if curLiteral.Len() > 0 {
		parts = append(parts, FormatPart{IsPlaceholder: false, Literal: curLiteral.String()})
	}
	return FormatString{IsFormat: true, Parts: parts}, nil
}

func printHelp() {
	term := os.Getenv("TERM")
	noColor := os.Getenv("NO_COLOR")
	isTTY := false
	if fi, err := os.Stdout.Stat(); err == nil && (fi.Mode()&os.ModeCharDevice) != 0 {
		isTTY = true
	}

	useColor := isTTY && term != "" && term != "dumb" && noColor == ""

	if useColor {
		fmt.Print("\x1b[1;35mtuc 1.3.0\x1b[0m\nCut text (or bytes) where a delimiter matches, then keep the desired parts.\n\n\x1b[1;32mUSAGE:\x1b[0m\n    \x1b[1;35mtuc [FLAGS] [OPTIONS] < input\x1b[0m\n    \x1b[1;35mtuc [FLAGS] [OPTIONS] filepath\x1b[0m\n\n\x1b[1;32mFLAGS:\x1b[0m\n   \x1b[1;36m -g\x1b[0m,\x1b[1;36m --greedy-delimiter\x1b[0m        Match consecutive delimiters as if it was one\n   \x1b[1;36m -p\x1b[0m,\x1b[1;36m --compress-delimiter\x1b[0m      Print only the first delimiter of a sequence\n   \x1b[1;36m -s\x1b[0m,\x1b[1;36m --only-delimited\x1b[0m          Print only lines containing the delimiter\n   \x1b[1;36m -V\x1b[0m,\x1b[1;36m --version\x1b[0m                 Print version information\n   \x1b[1;36m -z\x1b[0m,\x1b[1;36m --zero-terminated\x1b[0m         Line delimiter is NUL (\\0), not LF (\\n)\n   \x1b[1;36m -h\x1b[0m,\x1b[1;36m --help\x1b[0m                    Print this help and exit\n   \x1b[1;36m -m\x1b[0m,\x1b[1;36m --complement\x1b[0m              Invert fields (e.g. \x1b[33m'2'\x1b[0m becomes \x1b[33m'1,3:'\x1b[0m)\n   \x1b[1;36m -j\x1b[0m,\x1b[1;36m --(no-)join\x1b[0m               Print selected parts with delimiter in between\n   \x1b[1;36m --json\x1b[0m                        Print fields as a JSON array of strings\n   \x1b[1;36m --no-mmap\x1b[0m                     Disable memory mapping\n\n\x1b[1;32mOPTIONS:\x1b[0m\n   \x1b[1;36m -f\x1b[0m,\x1b[1;36m --fields\x1b[0m \x1b[33m<bounds>\x1b[0m         Fields to keep, 1-indexed, comma separated.\n                                  Use colon (:) to match a range (inclusive).\n                                  Use equal (=) to apply out of bound fallback.\n                                  Fields can be negative (\x1b[33m-1 \x1b[0mis the last field).\n                                  [\x1b[35mdefault\x1b[0m: \x1b[33m1:\x1b[0m]\n\n                                  e.g. cutting the string 'a-b-c-d' on '-'\n                                   \x1b[1;36m -f\x1b[0m \x1b[33m1\x1b[0m     => a\n       