	Raw      string
	Fallback *string
}

type RangeBound struct {
	Start    *int
	StartRaw string
	End      *int
	EndRaw   string
	Fallback *string
}

type BoundItem struct {
	IsRange bool
	Single  SingleBound
	Range   RangeBound
}

type BoundPlaceholder struct {
	Items []BoundItem
}

type FormatPart struct {
	IsPlaceholder bool
